export function MediaQueryDemo({
  viewportWidth = "{{viewportWidth}}",
  breakpoint = {{breakpoint}},
  accent = "{{accent}}",
}) {
  const chip = { background: accent, borderRadius: 6, padding: 10, textAlign: "center", fontWeight: 700 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430" }}
      role="img" aria-label="A row of chips that stack vertically below the breakpoint and lay out horizontally at or above it, like a media query switching layout by width">
      <style>{`@container mq (min-width: ${breakpoint}px) { .mq-row { flex-direction: row; } }`}</style>
      <div style={{ containerType: "inline-size", containerName: "mq", width: viewportWidth, border: "1.5px dashed #24143055",
        borderRadius: 8, padding: 12, boxSizing: "border-box", background: "#FAF7F2" }}>
        <div className="mq-row" style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={chip}>One</div><div style={chip}>Two</div><div style={chip}>Three</div>
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc", width: 320 }}>
        viewport {viewportWidth} &middot; @media (min-width: {breakpoint}px) switches the row from stacked to inline
      </p>
    </div>
  );
}
